`timescale 1ns/1ps

// Floating-point LIF neuron with a single transaction in flight.
//
// Update equation (E_rest = 0):
//   candidate = alpha * membrane + current
//   spike     = candidate >= threshold
//   membrane  = spike ? +0.0 : candidate
//
// Exact mode uses a Xilinx Floating-Point Operator multiplier. Approximate
// mode replaces only that multiplier with fp_mitchell_multiplier; the add and
// threshold compare remain exact Xilinx IP operations in both modes.
//
// The named IP modules are generated by vivado/create_fp_ip.tcl.
module fp_lif_neuron_xilinx #(
  parameter int WIDTH = 32,
  parameter bit APPROXIMATE = 1'b0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             soft_reset_i,
  input  logic             input_valid_i,
  output logic             input_ready_o,
  input  logic [WIDTH-1:0] current_i,
  input  logic [WIDTH-1:0] alpha_i,
  input  logic [WIDTH-1:0] threshold_i,
  output logic             output_valid_o,
  input  logic             output_ready_i,
  output logic [WIDTH-1:0] membrane_o,
  output logic             spike_o,
  output logic             busy_o
);
  typedef enum logic [3:0] {
    IDLE,
    LAUNCH_MULTIPLY,
    WAIT_MULTIPLY,
    LAUNCH_ADD,
    WAIT_ADD,
    LAUNCH_COMPARE,
    WAIT_COMPARE,
    HOLD_RESULT
  } state_t;

  state_t state;
  logic [WIDTH-1:0] current_reg;
  logic [WIDTH-1:0] alpha_reg;
  logic [WIDTH-1:0] threshold_reg;
  logic [WIDTH-1:0] product_reg;
  logic [WIDTH-1:0] candidate_reg;
  logic [WIDTH-1:0] mitchell_product;
  logic [WIDTH-1:0] multiply_result_data;
  logic             multiply_result_valid;
  logic [WIDTH-1:0] add_result_data;
  logic             add_result_valid;
  logic [7:0]       compare_result_data;
  logic             compare_result_valid;
  logic             multiply_input_valid;
  logic             add_input_valid;
  logic             compare_input_valid;
  logic             ip_aresetn;

  initial begin
    if (WIDTH != 16 && WIDTH != 32)
      $fatal(1, "WIDTH must be 16 or 32");
  end

  assign ip_aresetn = rst_ni && !soft_reset_i;
  assign input_ready_o = (state == IDLE);
  assign output_valid_o = (state == HOLD_RESULT);
  assign busy_o = (state != IDLE);
  assign multiply_input_valid = (state == LAUNCH_MULTIPLY);
  assign add_input_valid = (state == LAUNCH_ADD);
  assign compare_input_valid = (state == LAUNCH_COMPARE);

  generate
    if (WIDTH == 32) begin : gen_fp32
      fp_mitchell_multiplier #(
        .EXP_WIDTH(8),
        .FRAC_WIDTH(23)
      ) approximate_multiplier (
        .a_i(membrane_o),
        .b_i(alpha_i),
        .result_o(mitchell_product)
      );

      if (APPROXIMATE) begin : gen_approximate
        assign multiply_result_data = '0;
        assign multiply_result_valid = 1'b0;
      end else begin : gen_exact
        fp32_mul_exact exact_multiplier (
          .aclk(clk_i),
          .aresetn(ip_aresetn),
          .s_axis_a_tvalid(multiply_input_valid),
          .s_axis_a_tdata(membrane_o),
          .s_axis_b_tvalid(multiply_input_valid),
          .s_axis_b_tdata(alpha_reg),
          .m_axis_result_tvalid(multiply_result_valid),
          .m_axis_result_tdata(multiply_result_data)
        );
      end

      fp32_add_exact exact_adder (
        .aclk(clk_i),
        .aresetn(ip_aresetn),
        .s_axis_a_tvalid(add_input_valid),
        .s_axis_a_tdata(product_reg),
        .s_axis_b_tvalid(add_input_valid),
        .s_axis_b_tdata(current_reg),
        .m_axis_result_tvalid(add_result_valid),
        .m_axis_result_tdata(add_result_data)
      );

      fp32_cmp_ge_exact exact_comparator (
        .aclk(clk_i),
        .aresetn(ip_aresetn),
        .s_axis_a_tvalid(compare_input_valid),
        .s_axis_a_tdata(candidate_reg),
        .s_axis_b_tvalid(compare_input_valid),
        .s_axis_b_tdata(threshold_reg),
        .m_axis_result_tvalid(compare_result_valid),
        .m_axis_result_tdata(compare_result_data)
      );
    end else begin : gen_fp16
      fp_mitchell_multiplier #(
        .EXP_WIDTH(5),
        .FRAC_WIDTH(10)
      ) approximate_multiplier (
        .a_i(membrane_o),
        .b_i(alpha_i),
        .result_o(mitchell_product)
      );

      if (APPROXIMATE) begin : gen_approximate
        assign multiply_result_data = '0;
        assign multiply_result_valid = 1'b0;
      end else begin : gen_exact
        fp16_mul_exact exact_multiplier (
          .aclk(clk_i),
          .aresetn(ip_aresetn),
          .s_axis_a_tvalid(multiply_input_valid),
          .s_axis_a_tdata(membrane_o),
          .s_axis_b_tvalid(multiply_input_valid),
          .s_axis_b_tdata(alpha_reg),
          .m_axis_result_tvalid(multiply_result_valid),
          .m_axis_result_tdata(multiply_result_data)
        );
      end

      fp16_add_exact exact_adder (
        .aclk(clk_i),
        .aresetn(ip_aresetn),
        .s_axis_a_tvalid(add_input_valid),
        .s_axis_a_tdata(product_reg),
        .s_axis_b_tvalid(add_input_valid),
        .s_axis_b_tdata(current_reg),
        .m_axis_result_tvalid(add_result_valid),
        .m_axis_result_tdata(add_result_data)
      );

      fp16_cmp_ge_exact exact_comparator (
        .aclk(clk_i),
        .aresetn(ip_aresetn),
        .s_axis_a_tvalid(compare_input_valid),
        .s_axis_a_tdata(candidate_reg),
        .s_axis_b_tvalid(compare_input_valid),
        .s_axis_b_tdata(threshold_reg),
        .m_axis_result_tvalid(compare_result_valid),
        .m_axis_result_tdata(compare_result_data)
      );
    end
  endgenerate

  always_ff @(posedge clk_i) begin
    if (!rst_ni || soft_reset_i) begin
      state <= IDLE;
      current_reg <= '0;
      alpha_reg <= '0;
      threshold_reg <= '0;
      product_reg <= '0;
      candidate_reg <= '0;
      membrane_o <= '0;
      spike_o <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          spike_o <= 1'b0;
          if (input_valid_i) begin
            current_reg <= current_i;
            alpha_reg <= alpha_i;
            threshold_reg <= threshold_i;
            if (APPROXIMATE) begin
              product_reg <= mitchell_product;
              state <= LAUNCH_ADD;
            end else begin
              state <= LAUNCH_MULTIPLY;
            end
          end
        end

        LAUNCH_MULTIPLY:
          state <= WAIT_MULTIPLY;

        WAIT_MULTIPLY: begin
          if (multiply_result_valid) begin
            product_reg <= multiply_result_data;
            state <= LAUNCH_ADD;
          end
        end

        LAUNCH_ADD:
          state <= WAIT_ADD;

        WAIT_ADD: begin
          if (add_result_valid) begin
            candidate_reg <= add_result_data;
            state <= LAUNCH_COMPARE;
          end
        end

        LAUNCH_COMPARE:
          state <= WAIT_COMPARE;

        WAIT_COMPARE: begin
          if (compare_result_valid) begin
            spike_o <= compare_result_data[0];
            membrane_o <= compare_result_data[0] ? '0 : candidate_reg;
            state <= HOLD_RESULT;
          end
        end

        HOLD_RESULT: begin
          if (output_ready_i)
            state <= IDLE;
        end

        default:
          state <= IDLE;
      endcase
    end
  end
endmodule
